mapper.select:
SELECT COUNT(*) > 0
FROM house_wishlist
WHERE house_info_id = #{code} AND member_uuid = #{memberUuid};


SELECT w.id AS id, i.id AS house_info_id, sigungu_code, 
	emd_code, emd_name, house_type, jibun, road_name, building_name, build_year,
	latitude, longitude
FROM house_wishlist w
JOIN house_info i ON w.house_info_id = i.id
WHERE member_uuid = #{memberUuid}
ORDER BY id DESC
LIMIT #{requestDto.limitPlusOne} 
OFFSET #{requestDto.offset};
